parameters.jsCode:
// Erwartete Nachricht:
// /bewerben https://www.php-entwickler.de/job/...
// optional zweite Zeile: Firma | Position
// Dateien (PDF) als Reply/Attachments an dieselbe Nachricht

const msg = $input.first().json.message || $input.first().json;
const text = (msg.text || msg.caption || '').trim();
const chatId = msg.chat?.id;

if (!text.startsWith('/bewerben')) {
  return [{ json: { skip: true, chatId, reason: 'Kein /bewerben Befehl' } }];
}

const lines = text.split('\n').map(l => l.trim()).filter(Boolean);
const first = lines[0].replace('/bewerben', '').trim();
const jobUrl = first.match(/https?:\S+/)?.[0];
if (!jobUrl) {
  return [{ json: { skip: true, chatId, reason: 'Keine Job-URL gefunden. Nutzung: /bewerben <url>' } }];
}

const metaLine = lines[1] || '';
const [company = '', position = ''] = metaLine.split('|').map(s => s.trim());

const slug = (company || 'job')
  .toLowerCase()
  .replace(/[^a-z0-9äöüß]+/gi, '-')
  .replace(/^-|-$/g, '')
  .slice(0, 40);
const id = `${slug}-${Date.now().toString(36)}`;

const portal = jobUrl.includes('php-entwickler.de')
  ? 'php_entwickler'
  : jobUrl.includes('get-in-it.de')
    ? 'get_in_it'
    : 'external';

const docs = (msg.document ? [msg.document] : []).concat(msg.photo ? [] : []);
// Mehrere Dokumente kommen oft als separate Updates — hier Single-Doc Support.

return [{
  json: {
    skip: false,
    chatId,
    id,
    jobUrl,
    company: company || 'Unbekannt',
    position: position || 'Stelle',
    portal,
    folderRel: `data/applications/${id}`,
    documentFileId: msg.document?.file_id || null,
    documentFileName: msg.document?.file_name || 'lebenslauf.pdf'
  }
}];

