parameters.jsCode:
const fs = require('fs');
const path = require('path');
const root = $env.BEWERBUNG_BOT_ROOT;
const id = $('Befehl parsen').item.json.id;

// Bot verschiebt nach done/ oder failed/
const candidates = [
  path.join(root, 'data/done', id, 'result.json'),
  path.join(root, 'data/failed', id, 'result.json'),
  path.join(root, 'data/processing', id, 'result.json'),
];

let result = { success: false, message: 'result.json nicht gefunden' };
for (const p of candidates) {
  if (fs.existsSync(p)) {
    result = JSON.parse(fs.readFileSync(p, 'utf8'));
    result._path = p;
    break;
  }
}

return [{
  json: {
    chatId: $('Befehl parsen').item.json.chatId,
    id,
    ...result
  }
}];

